#[derive(Debug, Clone)]
struct BackgroundState {
    asset: String,
    transform: Transform,
}

/// 当前立绘状态。
#[derive(Debug, Clone)]
struct FigureState {
    track: usize,
    asset: Option<String>,
    live2d: Option<String>,
    expression: Option<String>,
    motion: Option<String>,
    /// 当前 motion 的起播时间; 只改表情时不重置。
    motion_start_us: u64,
    /// 当前表情的起播时间; 用于 exp3.json 的淡入淡出。
    expression_start_us: u64,
    blink: BlinkConfig,
    focus: FocusConfig,
    side: FigureSide,
    transform: Transform,
}

/// `setTransition` 登记、由下一次换图/换立绘消费的进出场动画 (一次性)。
